```python[]
class Solution:
    def findPath(self, grid):
        if not grid:
            return []

        if grid[0][0] == 0:
            return []

        ans = []
        n = len(grid)

        def is_move_safe(current_pos, direction, visited_str, visited_grid):
            if direction == 'D':
                if visited_str and visited_str[-1] == 'U':
                    return False, None
                elif current_pos[0]+1 == n:
                    return False, None
                elif grid[current_pos[0]+1][current_pos[1]] == 0:
                    return False, None
                elif visited_grid[current_pos[0]+1][current_pos[1]]:
                    return False, None
                else:
                    return True, (current_pos[0]+1, current_pos[1])
            elif direction == 'U':
                if visited_str and visited_str[-1] == 'D':
                    return False, None
                elif current_pos[0]-1 < 0:
                    return False, None
                elif grid[current_pos[0]-1][current_pos[1]] == 0:
                    return False, None
                elif visited_grid[current_pos[0]-1][current_pos[1]]:
                    return False, None
                else:
                    return True, (current_pos[0]-1, current_pos[1])
            elif direction == 'R':
                if visited_str and visited_str[-1] == 'L':
                    return False, None
                elif current_pos[1]+1 == n:
                    return False, None
                elif grid[current_pos[0]][current_pos[1]+1] == 0:
                    return False, None
                elif visited_grid[current_pos[0]][current_pos[1]+1]:
                    return False, None
                else:
                    return True, (current_pos[0], current_pos[1]+1)
            elif direction == 'L':
                if visited_str and visited_str[-1] == 'R':
                    return False, None
                elif current_pos[1]-1 < 0:
                    return False, None
                elif grid[current_pos[0]][current_pos[1]-1] == 0:
                    return False, None
                elif visited_grid[current_pos[0]][current_pos[1]-1]:
                    return False, None
                else:
                    return True, (current_pos[0], current_pos[1]-1)

        def move(current_pos, visited_str, visited_grid):

            if current_pos == (n-1, n-1):
                ans.append(visited_str)
                return

            for action in ['U', 'R', 'D', 'L']:
                is_action_safe, updated_pos = is_move_safe(current_pos, action, visited_str, visited_grid) 
                if is_action_safe:
                    visited_grid[updated_pos[0]][updated_pos[1]] = True

                    move(updated_pos, visited_str + action, visited_grid)

                    visited_grid[updated_pos[0]][updated_pos[1]] = False

        visited_grid = [[False for i in range(n)] for i in range(n)]
        visited_grid[0][0] = True
        move((0,0), "", visited_grid)

        return ans
```

